def name_operands(region,address,operation):
 if region!='Station':return operation
 for value,name in ((0xA235,'EndLimit'),(0xA25E,'ClearHeight'),(0xA265,'RenderCall')):
  operation=operation.replace('(#'+format(value,'04X')+')','(@ScrollState.'+name+')')
 if address!=0xA1D6:return operation
 for old,new in (('(#6307)','(@StationState.PointerXY)'),('(#6308)','(@StationState.PointerXY+1)'),('(#AEAB)','(@TextWindow.Height)'),('(#AEC7)','(@TextWindow.OriginYLow)'),('LD A, #17','LD A, @ScreenUpdateConst.CopyPage'),('LD A, #10','LD A, @ScreenUpdateConst.VisiblePage'),('LD A, #18','LD A, @ScreenUpdateConst.HiddenPage'),('LD HL, #5800','LD HL, @ScreenUpdateConst.BaseAttributes'),('LD DE, #D800','LD DE, @ScreenUpdateConst.BankAttributes'),('LD BC, #0300','LD BC, @ScreenUpdateConst.AttributeBytes'),('LD HL, #4000','LD HL, @ScreenUpdateConst.BaseScreen'),('LD DE, #C000','LD DE, @ScreenUpdateConst.BankWindow'),('LD BC, #1800','LD BC, @ScreenUpdateConst.BitmapBytes'),('AND #1F','AND @RowSelectConst.RowMask')):
  operation=operation.replace(old,new)
 return operation
